      plan_id      = aws_backup_plan.main.id
      name         = "all_tagged_resources"
      iam_role_arn = aws_iam_role.backup.arn

      selection_tag {
        type  = "STRINGEQUALS"
        key   = "backup"
        value = "true"
      }
    }

