  name = "example"

  point_in_time_recovery {
    enabled = true
  }
}

findings.recommendation:
Define a rotation configuration for every secret that supports it:

    resource "aws_secretsmanager_secret_rotation" "db" {
      secret_id           = aws_secretsmanager_secret.db.id
      rotation_lambda_arn = aws_lambda_function.rotate_secret.arn

      rotation_rules {
        automatically_after_days = 30
      }
    }

Use AWS-provided rotation Lambdas for RDS, Redshift, and DocumentDB secrets.
For custom secrets, implement the standard rotation Lambda contract.

findings.fix_hcl:
resource "aws_secretsmanager_secret_rotation" "example" {
  secret_id           = aws_secretsmanager_secret.example.id
  rotation_lambda_arn = aws_lambda_function.rotate_secret.arn
  rotation_rules {
    automatically_after_days = 30
  }
}

findings.recommendation:
Add a `version` constraint to every provider entry in `required_providers`:

    terraform {
      required_providers {
        google = {
          source  = "hashicorp/google"
          version = "~> 5.0"
        }
        aws = {
          source  = "hashicorp/aws"
          version = "~> 5.0"
        }
      }
    }

The `~> X.Y` pessimistic-constraint operator pins the major version while
allowing minor/patch updates. For production environments, consider exact
pinning (`= X.Y.Z`) and committing `.terraform.lock.hcl`.

findings.fix_hcl:
terraform {
  required_version = ">= 1.5.0, < 2.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    azurerm = {
      source  = "hashicorp/azurerm"
      version = "~> 3.0"
    }
  }
}

findings.recommendation:
Add a `server_side_encryption` block with a customer-managed KMS key:

    resource "aws_kms_key" "ddb" {
      description             = "DynamoDB table CMK"
      deletion_window_in_days = 30
      enable_key_rotation     = true
    }

    resource "aws_dynamodb_table" "app" {
      name = "app"

      server_side_encryption {
        enabled     = true
        kms_key_arn = aws_kms_key.ddb.arn
      }
    }

If a CMK is not yet available, the minimum acceptable baseline is
`server_side_encryption { enabled = true }` (AWS-managed key), which
at least makes the encryption choice explicit rather than implicit.

findings.fix_hcl:
resource "aws_dynamodb_table" "example" {
  name = "example"

  server_side_encryption {
    enabled     = true
    kms_key_arn = aws_kms_key.ddb.arn
  }
}

findings.recommendation:
Add an `aws_ecr_lifecycle_policy` resource to expire old images:

    resource "aws_ecr_lifecycle_policy" "main" {
      repository = aws_ecr_repository.main.name

      policy = jsonencode({
        rules = [{
          rulePriority = 1
          description  = "Expire untagged images older than 30 days"
          selection = {
            tagStatus   = "untagged"
            countType   = "sinceImagePushed"
            countUnit   = "days"
            countNumber = 30
          }
          action = { type = "expire" }
        }]
      })
    }

Without a lifecycle policy, ECR accumulates every pushed image indefinitely.
This increases storage cost and keeps stale (potentially vulnerable) images
in scope for scanners and attackers who reach the registry.

findings.fix_hcl:
resource "aws_ecr_lifecycle_policy" "example" {
  repository = aws_ecr_repository.example.name
  policy = jsonencode({
    rules = [{
      rulePriority = 1
      description  = "Expire untagged images after 30 days"
      selection = {
        tagStatus   = "untagged"
        countType   = "sinceImagePushed"
        countUnit   = "days"
        countNumber = 30
      }
      action = { type = "expire" }
    }]
  })
}

